[{"order":1,"type":"heading","text":"Mastering Dialogs, Alerts, and File Uploads/Downloads in Playwright"},{"order":2,"type":"paragraph","text":"Handling native browser dialogs, alerts, file uploads, and downloads are essential skills for end-to-end testing. Playwright provides robust, automatic, and event-driven APIs to interact with these browser features seamlessly without blocking test execution."},{"order":3,"type":"heading","text":"1. Handling JavaScript Dialogs and Alerts"},{"order":4,"type":"paragraph","text":"By default, Playwright automatically dismisses native dialogs (alert, confirm, prompt) if no listener is registered. To interact with them, you must register a dialog event handler using page.on('dialog', callback) before the action that triggers the dialog."},{"order":5,"type":"code","text":"const { test, expect } = require('@playwright/test');

test('handle alert and confirm dialogs', async ({ page }) => {
  await page.goto('https://example.com/alerts');

  // Handle a simple alert
  page.once('dialog', async dialog => {
    expect(dialog.type()).toBe('alert');
    expect(dialog.message()).toBe('Hello! I am an alert box!');
    await dialog.accept();
  });

  await page.click('#alert-button');

  // Handle a confirm dialog with dismissal
  page.once('dialog', async dialog => {
    expect(dialog.type()).toBe('confirm');
    await dialog.dismiss();
  });

  await page.click('#confirm-button');
});"},{"order":6,"type":"heading","text":"2. Handling Prompt Dialogs with Input"},{"order":7,"type":"paragraph","text":"Prompt dialogs require text input before acceptance. You can pass a string value into the dialog.accept(text) method."},{"order":8,"type":"code","text":"test('handle prompt dialog', async ({ page }) => {
  await page.goto('https://example.com/alerts');

  page.once('dialog', async dialog => {
    expect(dialog.type()).toBe('prompt');
    expect(dialog.defaultValue()).toBe('Default Value');
    await dialog.accept('Playwright Automation');
  });

  await page.click('#prompt-button');
  await expect(page.locator('#result')).toHaveText('Hello Playwright Automation! How are you today?');
});"},{"order":9,"type":"heading","text":"3. Uploading Files"},{"order":10,"type":"paragraph","text":"File uploads in Playwright are handled via the locator.setInputFiles() method. This works seamlessly even if the file input element is hidden in the DOM, as long as it exists."},{"order":11,"type":"code","text":"test('upload a single file', async ({ page }) => {
  await page.goto('https://example.com/upload');

  // Select the file input and upload a file from disk
  await page.locator('input[type="file"]').setInputFiles('path/to/upload/document.pdf');

  // Verify upload success
  await expect(page.locator('#success-message')).toBeVisible();
});"},{"order":12,"type":"bullet_point","text":"Multiple Files: Pass an array of file paths to setInputFiles(['file1.txt', 'file2.txt']) to upload multiple files simultaneously."},{"order":13,"type":"bullet_point","text":"Deselecting Files: Pass an empty array setInputFiles([]) to clear selected files."},{"order":14,"type":"heading","text":"4. Downloading Files"},{"order":15,"type":"paragraph","text":"To handle file downloads, wait for the 'download' event simultaneously with the action that triggers the download. Playwright stores downloads in a temporary directory that you can save to a specific path."},{"order":16,"type":"code","text":"test('download a file', async ({ page }) => {
  await page.goto('https://example.com/downloads');

  // Wait for the download event to occur
  const downloadPromise = page.waitForEvent('download');
  await page.click('#download-button');
  const download = await downloadPromise;

  // Optional: Extract suggested filename
  const fileName = download.suggestedFilename();
  console.log('Downloaded file name:', fileName);

  // Save the downloaded file to a desired path
  const savePath = './downloads/' + fileName;
  await download.saveAs(savePath);
});"},{"order":17,"type":"heading","text":"Summary"},{"order":18,"type":"paragraph","text":"By mastering page.on('dialog'), locator.setInputFiles(), and page.waitForEvent('download'), you can reliably handle native browser disruptions and data transfer flows in your Playwright test suites."}]
